sys_variable_value.value:
(function execute(inputs, outputs) {

  var currentID = inputs.currentRecord; //trocar depois para o record e não o sys_id

  var currentRecord = new GlideRecord("x_asscs_allos_o2c_task");
    if (currentRecord.get(currentID)) {

      var grLucParent = new GlideRecord('x_asscs_allos_o2c_requested_item');
      grLucParent.addEncodedQuery('parent=' + currentRecord.request_item + '^cat_item=173567c3873775501ee364640cbb3572'); //Item LUC
      grLucParent.query();

      if (grLucParent.next()) {
          var lucParentID = grLucParent.sys_id;
          var grLucTask = new GlideRecord('x_asscs_allos_o2c_task');
          grLucTask.addEncodedQuery('parent=' + lucParentID + '^order=2');
          grLucTask.query();
          if (grLucTask.next()) {
              var companyCode = grLucTask.variables.company_code.getDisplayValue();
          }
      }
    }

    var myObj = {
  "CompanyCode": companyCode,
  "ContractNumber": "10008214",
  "ContractEndDate": "2026-01-01",        
  "MonetaryCorrectionIndex": "IPCA", 
  "BaseYear": "1993",
  "BusinessPartners": [
    {
      "BPNumber": "10007392",
      "BPRoleCode": "TR0600",
      "BPValidTo": "2024-11-04"
    },
    {
      "BPNumber": "10002619",
      "BPRoleCode": "TR0600",      
      "BPValidFrom": "2024-11-05"
    }
  ],
  "TermPayments": [
    {
      "TermNumber" : "",
      "BPNumber": "10007392",
      "ValidFrom": "2022-01-01",
      "ValidTo": "2024-11-04"
    },
    {
      "TermNumber" : "",
      "BPNumber": "10002619",
      "ValidFrom": "2024-11-05"
    }
  ],
  "TermWithHoldingTaxes": [
    {
      "TermNumber": "",
      "TermText": "LOCATÁRIO",
      "BPNumber": "10007392",
      "ValidFrom": "2022-01-01",
      "ValidTo": "2024-11-04"
    },
    {
      "TermNumber": "",
      "TermText": "LOCATÁRIO",
      "BPNumber": "10002619",
      "ValidFrom": "2024-11-05"
    }
  ]  
}

outputs.payload = myObj;

})(inputs, outputs);

